    private static readonly Dictionary<string, Geometry> Cache = new(StringComparer.OrdinalIgnoreCase);

    /// <summary>Returns the raw SVG path data for an icon key (falls back to the box icon).</summary>
    public static string ResolvePath(string? key)
    {
        var name = string.IsNullOrWhiteSpace(key) ? FallbackKey : key!;
        return PathData.TryGetValue(name, out var path) ? path : PathData[FallbackKey];
    }

    /// <summary>Resolves an icon key (e.g. "bike") to a scalable geometry, falling back to the box icon.</summary>
    public static Geometry Resolve(string? key)
    {
        var name = string.IsNullOrWhiteSpace(key) ? FallbackKey : key!;
        if (Cache.TryGetValue(name, out var cached)) return cached;

        // Font Awesome paths carry an explicit F0 prefix; the rest use even-odd.
        var path = ResolvePath(name);
        var geometry = Geometry.Parse(path.StartsWith("F0 ", StringComparison.Ordinal) ||
                                      path.StartsWith("F1 ", StringComparison.Ordinal)
            ? path
            : "F1 " + path);
        Cache[name] = geometry;
        return geometry;
    }

    public static bool IsKnown(string? key) =>
        !string.IsNullOrWhiteSpace(key) && PathData.ContainsKey(key);

    public static Geometry DownloadIcon => Resolve("download");

    public static Geometry RefreshIcon => Resolve("refresh");

    public static Geometry PlayIcon => Resolve("play");

    public static Geometry FolderIcon => Resolve("folder");

    public static Geometry SettingsIcon => Resolve("gear");

    public static Geometry LogsIcon => Resolve("logs");

    public static IReadOnlyCollection<string> Keys => PathData.Keys;
}
